// ============================================================
// WF1 - Node Code: susun response pencarian resi.
// [UPDATE 2026-07-06]
//   MODE A (ada param resi): cari di sheet Tracking; bila tidak ketemu,
//     fallback cari di sheet Archive (resi lama tetap bisa dilacak).
//   MODE B (param resi KOSONG): kembalikan seluruh resi di Tracking yang
//     Timestamp_Update-nya dalam 30 hari terakhir (dipakai tombol
//     "Terapkan Filter" tanpa pencarian di frontend).
// - Parse Riwayat_Posisi_JSON dengan try/catch (aman dari JSON korup).
// - Resi tak ditemukan di mana pun => { no_resi, found:false }.
// ============================================================

// Rows dari kedua node sebelumnya. Dengan alwaysOutputData, sheet kosong
// menghasilkan satu item {} — baris tanpa No_Resi diabaikan di bawah.
const rows = $items('Baca Sheet Tracking').map(i => i.json);
const rowsArchive = $items('Baca Sheet Archive').map(i => i.json);

// Ambil query dari webhook. n8n menaruh query di .query.
const webhookData = $items('Webhook GET tracking-get')[0].json;
const query = webhookData.query || {};
const resiParamRaw = query.resi || '';

// Split daftar resi berdasarkan koma, normalisasi, buang yang kosong.
const daftarResi = String(resiParamRaw)
  .split(',')
  .map(r => r.trim().toUpperCase())
  .filter(r => r.length > 0);

// Susun satu entri response dari satu row sheet (parse riwayat aman).
function buildEntri(row, resiFallback, dariArsip) {
  let riwayat = [];
  let riwayatError = false;
  const raw = row.Riwayat_Posisi_JSON;
  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
    try {
      const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
      riwayat = Array.isArray(parsed) ? parsed : [];
      if (!Array.isArray(parsed)) riwayatError = true;
    } catch (e) {
      riwayat = [];
      riwayatError = true;
    }
  }
  const entri = {
    no_resi: String(row.No_Resi || resiFallback),
    found: true,
    pengirim: row.Pengirim || '',
    penerima: row.Penerima || '',
    status_terakhir: row.Status_Terakhir || '',
    timestamp_update: row.Timestamp_Update || '',
    riwayat: riwayat
  };
  if (riwayatError) entri.riwayat_error = true;
  if (dariArsip) entri.arsip = true;
  return entri;
}

// ── MODE B: tanpa param resi → semua resi Tracking 30 hari terakhir ──
if (daftarResi.length === 0) {
  const now = Date.now();
  const AMBANG_MS = 30 * 24 * 60 * 60 * 1000;
  const hasil = [];
  for (const row of rows) {
    if (!String(row.No_Resi || '').trim()) continue;
    const t = Date.parse(row.Timestamp_Update);
    if (isNaN(t) || (now - t) > AMBANG_MS) continue;
    hasil.push(buildEntri(row, row.No_Resi, false));
  }
  // Terbaru dulu, batasi 100 baris agar respons tetap ringan.
  hasil.sort((a, b) => Date.parse(b.timestamp_update) - Date.parse(a.timestamp_update));
  const dibatasi = hasil.slice(0, 100);
  return [{ json: { results: dibatasi, data: dibatasi, total: dibatasi.length, cakupan: 'terbaru-30-hari' } }];
}

// ── MODE A: pencarian per resi ──
// Index rows berdasarkan No_Resi (uppercase) untuk lookup cepat.
const indexResi = {};
for (const row of rows) {
  const key = String(row.No_Resi || '').trim().toUpperCase();
  if (key) indexResi[key] = row;
}
const indexArsip = {};
for (const row of rowsArchive) {
  const key = String(row.No_Resi || '').trim().toUpperCase();
  if (key) indexArsip[key] = row;
}

const hasil = [];
for (const resi of daftarResi) {
  const row = indexResi[resi];
  if (row) {
    hasil.push(buildEntri(row, resi, false));
    continue;
  }
  // Fallback: cari di Archive (resi lama yang sudah dipindah WF3).
  const rowArsip = indexArsip[resi];
  if (rowArsip) {
    hasil.push(buildEntri(rowArsip, resi, true));
    continue;
  }
  hasil.push({ no_resi: resi, found: false });
}

// Kembalikan satu item berisi array hasil (dipakai node Respond).
return [{ json: { results: hasil, data: hasil, total: hasil.length } }];
